  "command": "replace_content_by_matching",
  "args": {
    "old_content": "    // Sequential state register with asynchronous active-low reset
    initial begin
        state = S0;
        z = 1'b0;
    end

    always @(posedge clk or negedge aresetn) begin
        if (!aresetn) begin
            state <= S0;
            z <= 1'b0;
        end else begin
            state <= next_state;
            z <= z_next;
        end
    end
",
    "new_content": "    // Sequential state register with asynchronous active-low reset
    initial begin
        state = S0;
    end

    // Mealy output is combinational: assert z in the same cycle the sequence completes
    always @(*) begin
        z = z_next;
    end

    always @(posedge clk or negedge aresetn) begin
        if (!aresetn) begin
            state <= S0;
        end else begin
            state <= next_state;
        end
    end
"
  }
}

